DROP TABLE IF EXISTS `question_sets`;
CREATE TABLE `question_sets` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '题目集唯一标识符',
  `setName` varchar(100) NOT NULL COMMENT '题目集名称',
  `description` text COMMENT '题目集描述',
  `createTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `isDelete` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除（0：未删除，1：已删除）',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='题目集表';

