-- Table structure for question_set_map
-- ----------------------------
DROP TABLE IF EXISTS `question_set_map`;
CREATE TABLE `question_set_map` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '关联唯一标识符',
  `questionId` bigint NOT NULL COMMENT '题目ID',
  `setId` int NOT NULL COMMENT '题目集ID',
  `createTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `isDelete` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除（0：未删除，1：已删除）',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='题目与题目集关联表';

