-- ----------------------------
-- Table structure for students
-- ----------------------------
DROP TABLE IF EXISTS `students`;
CREATE TABLE `students` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '学生表主键ID，自增',
  `studentNumber` varchar(256) NOT NULL COMMENT '学号，唯一标识学生',
  `name` varchar(256) NOT NULL COMMENT '学生姓名',
  `className` varchar(256) NOT NULL COMMENT '班级名称',
  `userId` bigint NOT NULL COMMENT '用户ID，关联用户表',
  `createTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `isDelete` tinyint NOT NULL DEFAULT '0' COMMENT '是否删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `studentNumber` (`studentNumber`)
) ENGINE=InnoDB AUTO_INCREMENT=337 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='学生表';

